{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C34"],
      "claim": "Verapamil, a dimethoxyphenyl tertiary-amine calcium-channel blocker structurally related to the query, has absolute oral bioavailability of 52% in cirrhotic patients, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Noscapine, a dimethoxy-substituted isoquinoline alkaloid with a tertiary amine and lactone, shows ~30% absolute oral bioavailability in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Valbenazine, a dimethoxy-tetrahydroisoquinoline derivative, has approximately 49% absolute oral bioavailability in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "Donepezil, a dimethoxy-indanone with a basic piperidine, has essentially complete oral bioavailability (~100%) in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Urapidil, a methoxyphenyl piperazine with amide/uracil functionality, has 72-78% absolute oral bioavailability in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C44"],
      "claim": "Gallopamil, a trimethoxy verapamil analogue, has 96.3% oral bioavailability in humans.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All transferable experimental evidence from structurally related dimethoxyphenyl/tertiary-amine drugs (verapamil, noscapine, valbenazine, donepezil, urapidil, gallopamil) shows absolute oral bioavailability of 30-100%, well above the 20% threshold. The only sub-20% values occur under rifampicin co-treatment and are not applicable to the query. The physicochemical prior is mixed and low-confidence and does not outweigh consistent high-F measurements.",
  "evidence_gaps": [
    "No direct human pharmacokinetic data for the exact query molecule; extrapolation relies on analogues.",
    "The query's low neutral fraction and rotatable bond count near the Veber limit add some uncertainty.",
    "Rifampicin-interaction low-F records were excluded as condition-specific and not representative of intrinsic bioavailability."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

